begin;
alter table family_private.news_request_events alter column request_id drop not null,add column post_id bigint references public.posts(id)on delete set null,add column news_title text;
create or replace function family_private.request_event(rid uuid,kind text)returns void language sql security definer set search_path='' as $$insert into family_private.news_request_events(tenant_id,request_id,actor,actor_name,event,post_id,news_title)select r.tenant_id,r.id,auth.uid(),coalesce((select display_name from public.profiles where id=auth.uid()),'النظام'),kind,r.post_id,r.title from family_private.news_requests r where r.id=rid and r.tenant_id=family_private.current_tenant()and(kind<>'submitted'or not exists(select 1 from family_private.news_request_events e where e.request_id=rid and e.event='submitted'))$$;
do $$declare def text;begin select pg_get_functiondef('family_private.news_request_action(text,jsonb)'::regprocedure)into def;def:=replace(def,'select e.id,e.request_id,r.title,e.actor_name,e.event,e.created_at,r.post_id from family_private.news_request_events e join family_private.news_requests r','select e.id,e.request_id,coalesce(e.news_title,r.title)as title,e.actor_name,e.event,e.created_at,coalesce(e.post_id,r.post_id)as post_id from family_private.news_request_events e left join family_private.news_requests r');execute def;end$$;
create or replace function family_private.request_published_event()returns trigger language plpgsql security definer set search_path='' as $$declare kind text;begin
 if auth.uid()is null or family_private.current_tenant()is distinct from new.tenant_id then return new;end if;
 if new.published and(TG_OP='INSERT'or not old.published)then kind:='published';elsif new.moderation_status='pending'and(TG_OP='INSERT'or old.moderation_status is distinct from new.moderation_status)then kind:='sent_for_approval';else return new;end if;
 if new.source_request_id is not null then if TG_OP='UPDATE'and kind='published'then perform family_private.request_event(new.source_request_id,kind);end if;
 else insert into family_private.news_request_events(tenant_id,post_id,news_title,actor,actor_name,event)values(new.tenant_id,new.id,new.title,auth.uid(),coalesce((select display_name from public.profiles where id=auth.uid()),'النظام'),kind);end if;return new;end$$;
drop trigger request_published_audit on public.posts;
create trigger request_published_audit after insert or update of published,moderation_status on public.posts for each row execute function family_private.request_published_event();
-- Import only recorded facts from older records; never guess an earlier approver.
insert into family_private.news_request_events(tenant_id,request_id,actor,actor_name,event,created_at,post_id,news_title)select r.tenant_id,r.id,r.requester_id,p.display_name,'submitted',r.created_at,r.post_id,r.title from family_private.news_requests r join public.profiles p on p.id=r.requester_id where not exists(select 1 from family_private.news_request_events e where e.request_id=r.id and e.event='submitted');
insert into family_private.news_request_events(tenant_id,request_id,actor,actor_name,event,created_at,post_id,news_title)select r.tenant_id,r.id,r.reviewer_id,p.display_name,case when r.status='approved'then 'approved'else 'rejected'end,r.reviewed_at,r.post_id,r.title from family_private.news_requests r join public.profiles p on p.id=r.reviewer_id where r.status in('approved','rejected')and r.reviewed_at is not null and not exists(select 1 from family_private.news_request_events e where e.request_id=r.id and e.event in('approved','rejected'));
insert into family_private.news_request_events(tenant_id,post_id,news_title,actor_name,event,created_at)select p.tenant_id,p.id,p.title,'المعتمد السابق غير مسجل','published_legacy',coalesce(p.published_at,p.created_at)from public.posts p where p.published and not exists(select 1 from family_private.news_requests r where r.post_id=p.id)and not exists(select 1 from family_private.news_request_events e where e.post_id=p.id);
commit;
